// Times are epoch microseconds, generated by the server. The artboards write
// dates day-first ("12 Sep 2026") and times as 24-hour mono, so both are fixed
// rather than left to the locale.

const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun",
  "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const two = (n) => String(n).padStart(2, "0");

export function when(micros, withTime = false) {
  if (!micros) return "";
  const d = new Date(micros / 1000);
  const date = `${d.getDate()} ${MONTHS[d.getMonth()]} ${d.getFullYear()}`;
  return withTime ? `${date}, ${two(d.getHours())}:${two(d.getMinutes())}` : date;
}

/** A planned-end date string ("2026-09-12") in the artboards' format. */
export function whenDay(iso) {
  if (!iso) return "";
  const [y, m, day] = iso.split("-").map(Number);
  return `${two(day)} ${MONTHS[m - 1]} ${y}`;
}

/** Whole days from today to a planned-end date string; negative once past. */
export function daysUntil(iso) {
  const [y, m, day] = iso.split("-").map(Number);
  const today = new Date();
  return Math.round((new Date(y, m - 1, day) -
    new Date(today.getFullYear(), today.getMonth(), today.getDate())) / 86400000);
}

/** "now", "12 min", "2 h", "yesterday", "05 Sep" — the log and admin idiom. */
export function ago(micros) {
  if (!micros) return "never";
  const mins = Math.floor((Date.now() - micros / 1000) / 60000);
  if (mins < 1) return "now";
  if (mins < 60) return `${mins} min`;
  if (mins < 24 * 60) return `${Math.floor(mins / 60)} h`;
  if (mins < 48 * 60) return "yesterday";
  return when(micros);
}

export function clock(micros) {
  const d = new Date(micros / 1000);
  return `${two(d.getHours())}:${two(d.getMinutes())}:${two(d.getSeconds())}` +
    `.${String(Math.floor((micros / 1000) % 1000)).padStart(3, "0")}`;
}

export function initials(name) {
  if (!name) return "";
  const parts = String(name).trim().split(/[\s._-]+/).filter(Boolean);
  if (parts.length >= 2) return (parts[0][0] + parts[1][0]).toUpperCase();
  return name.slice(0, 2).toUpperCase();
}

export function plural(n, word) {
  return `${n} ${word}${n === 1 ? "" : "s"}`;
}

/** "+12 entries", what a glance at the log leaves out. */
export function moreEntries(n) {
  return `+${n} ${n === 1 ? "entry" : "entries"}`;
}
